import{_ as t,H as a,f as i,i as r}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语 | 拉开大模型和软件测试这场秀的幕","description":"","frontmatter":{},"headers":[{"level":2,"title":"测试技术的变与不变","slug":"测试技术的变与不变","link":"#测试技术的变与不变","children":[]},{"level":2,"title":"为什么说这个转变如此关键？","slug":"为什么说这个转变如此关键","link":"#为什么说这个转变如此关键","children":[]}],"relativePath":"AI重塑测试开发系统实践/结束语｜拉开大模型和软件测试这场秀的幕.md","filePath":"AI重塑测试开发系统实践/结束语｜拉开大模型和软件测试这场秀的幕.md","lastUpdated":1795562968000}'),n={name:"AI重塑测试开发系统实践/结束语｜拉开大模型和软件测试这场秀的幕.md"};function p(s,e,_,l,o,E){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="结束语-拉开大模型和软件测试这场秀的幕" tabindex="-1">结束语 | 拉开大模型和软件测试这场秀的幕 <a class="header-anchor" href="#结束语-拉开大模型和软件测试这场秀的幕" aria-label="Permalink to &quot;结束语 | 拉开大模型和软件测试这场秀的幕&quot;">​</a></h1><p>你好，我是陈磊。</p><p>这个小专栏到这里就结束了，不过这只是我陪你一起学习的结束，帮你拉开大模型和软件测试这场秀的幕之后，舞台上的你才是这场秀的主角。</p><h2 id="测试技术的变与不变" tabindex="-1">测试技术的变与不变 <a class="header-anchor" href="#测试技术的变与不变" aria-label="Permalink to &quot;测试技术的变与不变&quot;">​</a></h2><p>我读研究生的时候，接触到了 TTCN3 自动化测试编程语言，从那时开始喜欢上了软件测试这个方向。毕业后就从事了软件测试的工作，从业有十六年了，这十六年里面软件测试技术有了翻天覆地的变化。从我刚入行的手工测试用例设计、性能测试执行，到后来的流量录制回放、全链路压测、精准测试，测试技术的一路变革如果你错过了一些其实也没什么，终归并不是所有的被测系统都需要流量录制回放，也不是所有的业务都有全链路压测的需求，没有精准测试也并不会让我们交付的系统缺陷逃逸严重攀升，这其实是因为软件测试技术这么多年的发展并没有脱离原有范式的约束。</p><p>而大模型被视为软件工程领域的“颠覆者”，因为它从根本上重塑了软件开发的流程、工具和角色分工。传统软件工程范式强调手动编码、严格的交付流程，而大模型驱动的软件工程新时代则转向大模型辅助的迭代、意图导向开发。这种变化的核心在于，大模型将“代码生成”和“智能决策”自动化，让软件交付过程从“编写代码”转向“引导大模型”，从而提升效率、降低门槛，并催生新型工具链。</p><p>然而，当大模型的浪潮席卷而来时，软件测试这个曾经稳扎稳打的领域，也面临着前所未有的范式重塑。它不再是单纯的缺陷猎手的守护者，而是演变为风险守护者的战略引擎——从传统的手工执行和脚本自动化，跃升到 AI 驱动的生成式测试、自主探索和预测性缺陷注入。</p><p>这不仅仅是工具的升级，更是思维方式的颠覆，测试用例不再需要逐行敲写，而是通过自然语言意图描述，让大模型自动生成覆盖率更高的场景；缺陷预测不再依赖历史数据统计，而是借助大模型的语义理解，提前模拟边缘风险；甚至，整个测试流程都能实现端到端的自治，测试工程师从“测试执行者”转型为“AI 测试架构师”，负责设计提示词、验证模型输出，并融入业务语境。</p><h2 id="为什么说这个转变如此关键" tabindex="-1">为什么说这个转变如此关键？ <a class="header-anchor" href="#为什么说这个转变如此关键" aria-label="Permalink to &quot;为什么说这个转变如此关键？&quot;">​</a></h2><p>因为在软件工程 3.0 时代，如果测试环节仍固守旧范式，我们将面临双重危机：一方面，代码生成的速度远超测试验证，导致交付链条的“瓶颈”从开发移到测试，稍有滞后，整个生态就崩盘；另一方面，大模型生成的代码往往隐含着“黑箱”风险——幻觉、偏置或未预见的逻辑漏洞——如果没有与之匹配的智能测试能力，这些隐患会像雪球般滚大，酿成生产事故。</p><p>回想我这十六年的从业路，从 TTCN3 的协议测试到如今的云原生压测，每一次技术迭代都让我感慨，测试从来不是可有可无的附属品，而是软件可靠性的脊梁骨。而今，大模型的介入，让这个脊梁骨变得更坚韧、更智能，但也更需要我们主动拥抱和驾驭。</p><p>这就是为什么我开始动笔撰写这个专栏的初心，它不是一堂枯燥的理论课，而是我们共同的实战实验室。在这里，我们一起拆解大模型在测试中的落地路径——从提示词工程优化用例生成，到 RAG 增强接口测试用例生成，再到 MCP Server 武装 Agent 实现自动化测试的闭环。</p><p>我分享的不是高高在上的概念，而是从一线痛点出发的案例。这些内容，每一篇都源于我这些年的积累和对未来的预判，旨在让你不只是“知道”大模型能做什么，而是会用它来辅助你的测试职业生涯。</p><p>专栏虽暂告一段落，但学习永无止境。这场秀的帷幕虽由我拉开，但聚光灯下，你的每一次实验、每一次迭代，才是真正的主旋律。未来，软件测试将与大模型深度融合，催生出“零缺陷交付”的黄金时代，而你，已然握住了通往那里的钥匙。欢迎随时回来讨论、分享你的心得和感悟。让我们继续前行，一起见证测试从被动防御到主动赋能的华丽转身。你的舞台，已然就绪，行动起来吧！</p><p>听我讲了这么多，最后我也想听听你的声音，希望你能花几分钟的时间填写一下结课问卷，提出你的意见或建议。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p>',16)])])}const B=t(n,[["render",p]]);export{c as __pageData,B as default};
